// Proof that the one Anthropic client (lib/anthropic.js) changed nothing: for every AI feature and every simulated
// answer (ok, odd shapes, 400 credit, 402, 401, 429, 500, 529, network, timeout, oversize, no key, cap reached) the
// outgoing request, the result, the usage rows, the credit-alert calls, the cap calls, the timeouts and the log lines
// equal what the code from before the refactor (origin/main of 2026-10-23) produced. The golden file was generated by
// scripts/ai-golden.js against that code; test/helpers/aiMatrix.js is the harness. No network, no real key.
const { test } = require("node:test");
const assert = require("node:assert/strict");
const path = require("node:path");
const { runMatrix } = require("../helpers/aiMatrix");
const golden = require("../fixtures/ai-client-golden.json");

test("the golden matrix covers every feature and scenario", () => {
  const keys = Object.keys(golden);
  // 189 since the book description translation was removed (2026-10-28): the collection translations still cover the
  // "translation" feature (collection translate to French / blurb).
  assert.ok(keys.length >= 189, `matrix has ${keys.length} cases`);
  for (const f of ["description", "genre", "cover", "price", "price (override model)", "price lookup (caps, cache row)", "collection suggestions (ask)", "collection translate to French", "collection translate blurb"]) {
    assert.ok(keys.some((k) => k.startsWith(`${f} | `)), `feature ${f}`);
  }
  for (const s of ["400 credit balance too low", "429 rate limit", "529 overloaded", "network error", "timeout (no answer)", "200 oversize body", "daily cap reached", "no API key"]) {
    assert.ok(keys.some((k) => k.endsWith(` | ${s}`)), `scenario ${s}`);
  }
});

test("every feature x scenario behaves exactly as before the refactor", async () => {
  const now = await runMatrix(path.join(__dirname, "../.."));
  assert.deepEqual(Object.keys(now), Object.keys(golden));
  const diffs = [];
  for (const k of Object.keys(golden)) {
    try { assert.deepEqual(now[k], golden[k]); } catch (err) { diffs.push(`${k}\n${String(err.message).slice(0, 600)}`); }
  }
  assert.equal(diffs.length, 0, `${diffs.length} case(s) differ:\n${diffs.slice(0, 3).join("\n---\n")}`);
});
